import Foundation
import Observation
import BotcampCore

/// Loads the bundled, data-only course.json (generated by scripts/build-course.mjs).
@Observable
final class CourseStore {
    let course: Course
    let planner: PathPlanner

    init(bundle: Bundle = .main) {
        guard let url = bundle.url(forResource: "course", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let course = try? Course.decode(data) else {
            fatalError("course.json missing or invalid. Run: node scripts/build-course.mjs")
        }
        self.course = course
        self.planner = PathPlanner(course: course)
    }

    func unit(containing lessonId: String) -> BotcampCore.Unit? {
        course.units.first { $0.lessons.contains { $0.id == lessonId } }
    }
}
